        out[i] = result.x
    return out



def _poly(x,d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:,p],axis=1) for k in range(1,d+1) for p in combinations_with_replacement(range(x.shape[1]),k)])


def run_node(inputs: dict) -> dict:
